INSERT INTO "public"."medicines" ("id", "name", "generic_name", "description", "dosage_strength", "unit", "usage_instructions", "available_quantity", "is_active", "created_at", "updated_at") VALUES ('10000000-0000-0000-0000-000000000001', 'Amlodipine (Besilate)', 'Amlodipine', 'For treatment of high blood pressure and angina.', '5mg', 'Tablet', 'Take 1 tablet daily or as directed by doctor.', 150, true, '2026-07-13 12:13:08.038343+00', '2026-07-13 12:13:08.038343+00'), ('10000000-0000-0000-0000-000000000002', 'Metformin (Hydrochloride)', 'Metformin', 'For management of type 2 diabetes.', '500mg', 'Tablet', 'Take 1 tablet twice daily with meals.', 200, true, '2026-07-13 12:13:08.038343+00', '2026-07-13 12:13:08.038343+00'), ('10000000-0000-0000-0000-000000000003', 'Losartan (Potassium)', 'Losartan', 'For hypertension management and renal protection.', '50mg', 'Tablet', 'Take 1 tablet daily in the morning.', 120, true, '2026-07-13 12:13:08.038343+00', '2026-07-13 12:13:08.038343+00'), ('10000000-0000-0000-0000-000000000004', 'Paracetamol', 'Paracetamol', 'For relief of mild to moderate pain and fever.', '500mg', 'Tablet', 'Take 1-2 tablets every 4-6 hours as needed.', 300, true, '2026-07-13 12:13:08.038343+00', '2026-07-13 12:13:08.038343+00'), ('10000000-0000-0000-0000-000000000005', 'Salbutamol (Ventolin)', 'Salbutamol', 'For relief of bronchospasm in asthma.', '100mcg/dose', 'Inhaler', 'Inhale 1-2 puffs as needed for shortness of breath.', 30, true, '2026-07-13 12:13:08.038343+00', '2026-07-13 12:13:08.038343+00');